// Filter to only Google Docs and classify by title pattern
const files = $input.all().map(item => item.json);

const docs = files.filter(f =>
  f.mimeType === 'application/vnd.google-apps.document'
);

if (docs.length === 0) {
  return [{ json: { _empty: true } }];
}

// Classify content type based on title patterns
const classified = docs.map(doc => {
  let content_type = 'ground_note'; // default
  const titleLower = (doc.name || '').toLowerCase();

  if (titleLower.includes('ad copy') || titleLower.includes('ad_copy') ||
      titleLower.includes('social media') || titleLower.includes('facebook') ||
      titleLower.includes('instagram') || titleLower.includes('social post')) {
    content_type = 'ad_copy';
  } else if (titleLower.includes('field note') || titleLower.includes('ground') ||
             titleLower.includes('delivery note') || titleLower.includes('driver')) {
    content_type = 'ground_note';
  }

  return {
    json: {
      google_doc_id: doc.id,
      title: doc.name,
      content_type: content_type,
      google_last_modified: doc.modifiedTime,
      author: doc.lastModifyingUser?.displayName || 'Unknown',
      doc_url: `https://docs.google.com/document/d/${doc.id}/edit`
    }
  };
});

return classified;

// Combine doc metadata with extracted text content
const docContent = $input.first().json;

// Google Docs node returns the document body as structured content
// Extract plain text from paragraphs
let textContent = '';
try {
  if (docContent.body && docContent.body.content) {
    textContent = docContent.body.content.map(block => {
      if (block.paragraph) {
        return block.paragraph.elements?.map(el => el.textRun?.content || '').join('');
      }
      return '';
    }).join('');
  } else if (docContent.text) {
    textContent = docContent.text;
  } else {
    // Fallback: stringify and truncate
    textContent = JSON.stringify(docContent).substring(0, 5000);
  }
} catch (e) {
  textContent = 'Error extracting content: ' + e.message;
}

// Get metadata from the classified item
// Note: For batched items, n8n processes one at a time through the loop
const meta = $('Filter & Classify').first().json;

return [{
  json: {
    google_doc_id: meta.google_doc_id,
    content_type: meta.content_type,
    title: meta.title,
    body: textContent.trim(),
    author: meta.author,
    google_last_modified: meta.google_last_modified,
    doc_url: meta.doc_url,
    tags: []
  }
}];
